const d = $input.first().json;
const limpiar = (v) => String(v ?? '').trim();

const registro = {
  negocio: limpiar(d['Nombre del negocio']),
  contacto: limpiar(d['Nombre de contacto']),
  correo: limpiar(d['Correo']).toLowerCase(),
  tipo: limpiar(d['Tipo de negocio']),
  necesidad: limpiar(d['Necesidad principal']),
  notas: limpiar(d['Notas']),
  creado: new Date().toISOString(),
};

const errores = [];
if (!registro.negocio) errores.push('Falta el nombre del negocio');
if (!registro.contacto) errores.push('Falta el nombre de contacto');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(registro.correo)) errores.push('El correo no es válido');

const tareasBase = [
  { dia: 1, tarea: 'Reunión de bienvenida' },
  { dia: 2, tarea: 'Recoger accesos y materiales' },
  { dia: 3, tarea: 'Definir objetivos del mes' },
];

const porNecesidad = {
  'Redes sociales': [
    { dia: 4, tarea: 'Auditar los perfiles actuales' },
    { dia: 5, tarea: 'Crear calendario de contenido (4 semanas)' },
    { dia: 7, tarea: 'Programar las primeras 8 publicaciones' },
  ],
  'Campañas de correo y mensajes': [
    { dia: 4, tarea: 'Importar y limpiar la lista de contactos' },
    { dia: 5, tarea: 'Redactar la primera campaña' },
    { dia: 7, tarea: 'Configurar envío y aprobación' },
  ],
  'Reportes y métricas': [
    { dia: 4, tarea: 'Conectar las fuentes de datos' },
    { dia: 5, tarea: 'Armar el tablero de métricas' },
    { dia: 7, tarea: 'Programar el reporte semanal' },
  ],
};

let extra = porNecesidad[registro.necesidad];
if (registro.necesidad === 'Todo lo anterior') {
  extra = [
    { dia: 4, tarea: 'Auditar perfiles, contactos y fuentes de datos' },
    { dia: 6, tarea: 'Proponer un plan combinado de redes, correo y reportes' },
    { dia: 7, tarea: 'Acordar prioridades con el cliente' },
  ];
}
if (!extra) extra = [];

return [{
  json: {
    ...registro,
    valido: errores.length === 0,
    errores,
    tareas: [...tareasBase, ...extra],
  },
}];
